Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "calculate": "!isValid(datum[''Razão de preço etanol/gasolina'']) ? ''—'' : datum[''Razão de preço etanol/gasolina''] < datum[''Razão de rendimento do carro''] ? ''etanol ('' + format(datum[''Razão de rendimento do carro''] - datum[''Razão de preço etanol/gasolina''], ''.1%'') + '' abaixo do limite)'' : ''gasolina ('' + format(datum[''Razão de preço etanol/gasolina''] - datum[''Razão de rendimento do carro''], ''.1%'') + '' acima do limite)''",
      "as": "Compensa"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rule",
        "color": "#C8C6C4",
        "strokeDash": [
          4,
          3
        ]
      },
      "encoding": {
        "y": {
          "datum": 0.7
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "top",
        "dy": 3,
        "fontSize": 9,
        "color": "#605E5C"
      },
      "encoding": {
        "x": {
          "value": {
            "expr": "width - 4"
          }
        },
        "y": {
          "datum": 0.7
        },
        "text": {
          "value": "regra dos 70 %"
        }
      }
    },
    {
      "transform": [
        {
          "window": [
            {
              "op": "row_number",
              "as": "i"
            }
          ]
        },
        {
          "filter": "datum.i == 1"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "rule",
            "color": "#E0B000",
            "strokeWidth": 2
          },
          "encoding": {
            "y": {
              "field": "Razão de rendimento do carro",
              "type": "quantitative"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "bottom",
            "dy": -3,
            "fontSize": 9,
            "color": "#967100",
            "fontWeight": "bold"
          },
          "encoding": {
            "x": {
              "value": 4
            },
            "y": {
              "field": "Razão de rendimento do carro",
              "type": "quantitative"
            },
            "text": {
              "value": "rendimento do carro: abaixo, o etanol compensa"
            }
          }
        }
      ]
    },
    {
      "mark": {
        "type": "line",
        "color": "#191919",
        "interpolate": "monotone"
      },
      "encoding": {
        "x": {
          "field": "Mês",
          "type": "temporal",
          "timeUnit": "yearmonth",
          "title": null,
          "axis": {
            "format": "%Y",
            "tickCount": "year",
            "labelAlign": "left",
            "labelPadding": 6,
            "labelOverlap": "greedy"
          }
        },
        "y": {
          "field": "Razão de preço etanol/gasolina",
          "type": "quantitative",
          "title": "Etanol ÷ gasolina (preço do litro)",
          "scale": {
            "zero": false
          },
          "axis": {
            "format": ".0%",
            "tickCount": 5
          }
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "size": 40,
        "opacity": 0.01
      },
      "encoding": {
        "x": {
          "field": "Mês",
          "type": "temporal",
          "timeUnit": "yearmonth",
          "title": null,
          "axis": {
            "format": "%Y",
            "tickCount": "year",
            "labelAlign": "left",
            "labelPadding": 6,
            "labelOverlap": "greedy"
          }
        },
        "y": {
          "field": "Razão de preço etanol/gasolina",
          "type": "quantitative"
        },
        "tooltip": [
          {
            "field": "Mês",
            "type": "temporal",
            "timeUnit": "yearmonth",
            "title": "Mês",
            "format": "%b/%Y"
          },
          {
            "field": "Razão de preço etanol/gasolina",
            "title": "Etanol ÷ gasolina",
            "format": ".1%"
          },
          {
            "field": "Razão de rendimento do carro",
            "title": "Rendimento do carro",
            "format": ".1%"
          },
          {
            "field": "Compensa",
            "title": "Compensa abastecer com"
          }
        ]
      }
    }
  ]
}'
